func (a *CLIDiscoveryAdapter) Run(ctx context.Context) error {
    // ... existing: read README, start session, select persona ...

    // Get register from session for question text selection
    session, _ := a.handler.GetSession(sessionID)
    register := session.Register()

    // Iterate through all questions
    questions := domain.QuestionCatalog()
    for i, question := range questions {
        // Select text based on register
        var text string
        if register == domain.RegisterTechnical {
            text = question.TechnicalText()
        } else {
            text = question.NonTechnicalText()
        }

        fmt.Printf("Q%d/10\n", i+1)
        answer, err := a.prompter.AskQuestion(ctx, text)
        if errors.Is(err, context.Canceled) {
            return err
        }

        if answer == "" {
            reason, err := a.prompter.AskSkipReason(ctx)
            if errors.Is(err, context.Canceled) {
                return err
            }
            if _, err := a.handler.SkipQuestion(sessionID, question.ID(), reason); err != nil {
                return fmt.Errorf("skipping question %s: %w", question.ID(), err)
            }
        } else {
            if _, err := a.handler.AnswerQuestion(sessionID, question.ID(), answer); err != nil {
                return fmt.Errorf("answering question %s: %w", question.ID(), err)
            }
        }

        // Handle playback check every 3 questions (domain rule)
        // TODO: Check session.Status() for StatusPlaybackPending
    }
    return nil
}
