    huh.NewOption("Developer (technical background)", "1"),
    huh.NewOption("Product Owner (defines what to build)", "2"),
    huh.NewOption("Domain Expert (business knowledge)", "3"),
    huh.NewOption("Mixed / Other", "4"),
