func (h *RescueHandler) ExecutePlan(ctx context.Context, analysis *GapAnalysis) error {
    // ... existing file writes ...

    // Run tests after scaffolding
    framework, err := h.testRunner.Detect(ctx, analysis.ProjectDir())
    if err \!= nil {
        return h.rollback(ctx, analysis, fmt.Errorf("detect tests: %w", err))
    }

    if framework \!= "" {
        if err := h.testRunner.Run(ctx, analysis.ProjectDir(), framework); err \!= nil {
            return h.rollback(ctx, analysis, err)
        }
    }

    // Complete successfully
    return analysis.Complete()
}

func (h *RescueHandler) rollback(ctx context.Context, analysis *GapAnalysis, cause error) error {
    _ = h.gitOps.CheckoutPrevious(ctx, analysis.ProjectDir())
    _ = h.gitOps.DeleteBranch(ctx, analysis.ProjectDir(), branchName)
    return fmt.Errorf("rollback after test failure: %w", cause)
}
```

