### StdinPrompter Implementation

```go
// internal/discovery/infrastructure/stdin_prompter.go
package infrastructure

import (
    "bufio"
    "context"
    "fmt"
    "io"
    "strings"

    "github.com/alty-cli/alty/internal/discovery/application"
)

var _ application.Prompter = (*StdinPrompter)(nil)

type StdinPrompter struct {
    reader *bufio.Scanner
    writer io.Writer
}

func NewStdinPrompter(r io.Reader, w io.Writer) *StdinPrompter {
    return &StdinPrompter{
        reader: bufio.NewScanner(r),
        writer: w,
    }
}

// SelectPersona displays numbered choices and reads selection.
// Returns "1"-"4" matching domain persona choices.
func (p *StdinPrompter) SelectPersona(ctx context.Context) (string, error) {
    fmt.Fprintln(p.writer, "Which best describes you?")
    fmt.Fprintln(p.writer, "1. Developer (technical background)")
    fmt.Fprintln(p.writer, "2. Product Owner (defines what to build)")
    fmt.Fprintln(p.writer, "3. Domain Expert (business knowledge)")
    fmt.Fprintln(p.writer, "4. Mixed / Other")
    fmt.Fprint(p.writer, "Enter choice (1-4): ")

    if \!p.reader.Scan() {
        return "", context.Canceled // EOF
    }
    choice := strings.TrimSpace(p.reader.Text())
    return choice, nil
}

// AskQuestion displays question and reads multi-line answer.
// Empty input (just Enter) returns "" to signal skip.
func (p *StdinPrompter) AskQuestion(ctx context.Context, question string) (string, error) {
    fmt.Fprintf(p.writer, "%s\n", question)
    fmt.Fprintln(p.writer, "(Press Enter with empty input to skip)")
    fmt.Fprint(p.writer, "> ")

    if \!p.reader.Scan() {
        return "", context.Canceled
    }
    return strings.TrimSpace(p.reader.Text()), nil
}

// AskSkipReason prompts for skip reason.
func (p *StdinPrompter) AskSkipReason(ctx context.Context) (string, error) {
    fmt.Fprint(p.writer, "Reason for skipping? ")

    if \!p.reader.Scan() {
        return "", context.Canceled
    }
    return strings.TrimSpace(p.reader.Text()), nil
}

// ConfirmPlayback displays summary and asks yes/no.
func (p *StdinPrompter) ConfirmPlayback(ctx context.Context, summary string) (bool, error) {
    fmt.Fprintln(p.writer, "Review your answers:")
    fmt.Fprintln(p.writer, summary)
    fmt.Fprint(p.writer, "Continue? (y/n): ")

    if \!p.reader.Scan() {
        return false, context.Canceled
    }
    answer := strings.ToLower(strings.TrimSpace(p.reader.Text()))
    return answer == "y" || answer == "yes", nil
}
```

### Test Strategy

Use `bytes.Buffer` for I/O injection:

```go
func TestStdinPrompter_SelectPersona(t *testing.T) {
    input := bytes.NewBufferString("2\n")
    output := &bytes.Buffer{}
    p := NewStdinPrompter(input, output)

    choice, err := p.SelectPersona(context.Background())
    require.NoError(t, err)
    assert.Equal(t, "2", choice)
    assert.Contains(t, output.String(), "Developer")
}
```
